[patterns/application/micro-frontend/PTN-APP-MFE-008-micro-frontend-integration-overview.md#pattern-1-shell-provided-props-implementation]

#### Pattern 1: Shell-Provided Props Implementation

**Shell Application:**

```typescript
// shell/src/App.tsx
import { useEffect, useState } from 'react';
import { MicroFrontend } from './MicroFrontend';

interface MfeContext {
  user: User;
  config: AppConfig;
  featureFlags: FeatureFlags;
  apiBaseUrl: string;
  events: EventBus;
}

export function App() {
  const [context, setContext] = useState<MfeContext | null>(null);

  useEffect(() => {
    async function initializeApp() {
      // Fetch shared state once at application startup
      const [user, config, featureFlags] = await Promise.all([
        authService.getCurrentUser(),
        configService.getAppConfig(),
        featureFlagService.getFlags(),
      ]);

      setContext({
        user,
        config,
        featureFlags,
        apiBaseUrl: config.apiBaseUrl,
        events: new EventBus(),
      });
    }

    initializeApp();
  }, []);

  if (!context) return <LoadingSpinner />;

  return (
    <div>
      <Header user={context.user} />
      <Routes>
        <Route
          path="/claims/*"
          element={<MicroFrontend name="claims" context={context} />}
        />
        <Route
          path="/provider/*"
          element={<MicroFrontend name="provider" context={context} />}
        />
      </Routes>
    </div>
  );
}
```

**Micro-Frontend Consumer:**

```typescript
// claims-mfe/src/index.tsx
import { MfeContext } from '@gainwell/mfe-types';

export function mount(container: HTMLElement, context: MfeContext) {
  const root = ReactDOM.createRoot(container);

  root.render(
    <ClaimsApp
      user={context.user}              // Read-only prop
      apiBaseUrl={context.apiBaseUrl}  // Read-only prop
      featureFlags={context.featureFlags}  // Read-only prop
    />
  );

  return () => root.unmount();
}

function ClaimsApp({ user, apiBaseUrl, featureFlags }) {
  // Use props as read-only data
  const canSubmitClaims = featureFlags.claimsSubmissionEnabled;

  return (
    <div>
      <h1>Welcome, {user.displayName}</h1>
      {canSubmitClaims && <ClaimSubmissionForm apiBaseUrl={apiBaseUrl} />}
    </div>
  );
}
```

**When to Use:**
- ✅ User profile (identity, name, roles, permissions)
- ✅ Feature flags (read-only, change requires app reload)
- ✅ Application configuration (API URLs, environment settings)
- ✅ Theme/locale preferences
- ❌ Shopping cart (changes frequently, needs real-time sync) → Use Shared Context
- ❌ Notifications (real-time updates) → Use Event Bus
- ❌ Large datasets (member lists, claim history) → Use Backend API

