[patterns/application/micro-frontend/PTN-APP-MFE-008-micro-frontend-integration-overview.md#pattern-2-event-bus-implementation]

#### Pattern 2: Event Bus Implementation

**Event Bus (Shell):**

```typescript
// shell/src/services/EventBus.ts
import { z } from 'zod';

// Define typed event schemas
const ClaimSubmittedEventSchema = z.object({
  claimId: z.string(),
  memberId: z.string(),
  providerId: z.string(),
  amount: z.number(),
  submittedAt: z.string().datetime(),
});

const EligibilityChangedEventSchema = z.object({
  memberId: z.string(),
  previousStatus: z.enum(['ACTIVE', 'INACTIVE', 'PENDING']),
  newStatus: z.enum(['ACTIVE', 'INACTIVE', 'PENDING']),
  effectiveDate: z.string().date(),
});

type ClaimSubmittedEvent = z.infer<typeof ClaimSubmittedEventSchema>;
type EligibilityChangedEvent = z.infer<typeof EligibilityChangedEventSchema>;

export class EventBus {
  private handlers = new Map<string, Array<(data: any) => void>>();

  // Publish event with schema validation
  publish<T>(eventType: string, data: T, schema: z.ZodSchema<T>) {
    try {
      const validatedData = schema.parse(data);

      const handlers = this.handlers.get(eventType) || [];
      handlers.forEach(handler => {
        try {
          handler(validatedData);
        } catch (error) {
          console.error(`Error in event handler for ${eventType}:`, error);
          // Report to error tracking, but don't throw (fire-and-forget)
        }
      });

      // Log event for observability
      this.logEvent(eventType, validatedData);
    } catch (error) {
      console.error(`Event schema validation failed for ${eventType}:`, error);
      throw error; // Publisher should know about schema violations
    }
  }

  // Subscribe to event type
  subscribe<T>(eventType: string, handler: (data: T) => void): () => void {
    if (!this.handlers.has(eventType)) {
      this.handlers.set(eventType, []);
    }

    this.handlers.get(eventType)!.push(handler);

    // Return unsubscribe function
    return () => {
      const handlers = this.handlers.get(eventType) || [];
      const index = handlers.indexOf(handler);
      if (index > -1) {
        handlers.splice(index, 1);
      }
    };
  }

  private logEvent(eventType: string, data: any) {
    // Send to observability platform (DataDog, CloudWatch)
    console.log(`[EventBus] ${eventType}`, data);
  }
}
```

**Publisher (Claims MFE):**

```typescript
// claims-mfe/src/components/ClaimSubmissionForm.tsx
import { ClaimSubmittedEventSchema } from '@gainwell/mfe-events';

function ClaimSubmissionForm({ context }: { context: MfeContext }) {
  async function handleSubmit(claimData) {
    // Submit claim to backend
    const claim = await claimsApi.submitClaim(claimData);

    // Publish domain event for other modules
    context.events.publish(
      'claim.submitted',
      {
        claimId: claim.id,
        memberId: claim.memberId,
        providerId: claim.providerId,
        amount: claim.totalAmount,
        submittedAt: new Date().toISOString(),
      },
      ClaimSubmittedEventSchema
    );
  }

  return <form onSubmit={handleSubmit}>...</form>;
}
```

**Subscriber (Care Coordination MFE):**

```typescript
// carecoord-mfe/src/hooks/useClaimEvents.ts
import { useEffect } from 'react';
import { ClaimSubmittedEvent } from '@gainwell/mfe-events';

export function useClaimEvents(context: MfeContext) {
  useEffect(() => {
    // Subscribe to claim submitted events
    const unsubscribe = context.events.subscribe<ClaimSubmittedEvent>(
      'claim.submitted',
      async (event) => {
        console.log('Received claim.submitted event:', event);

        // Trigger care gap analysis for member
        try {
          await careGapService.analyzeCaregaps(event.memberId);
          console.log(`Care gap analysis triggered for member ${event.memberId}`);
        } catch (error) {
          console.error('Failed to analyze care gaps:', error);
          // Error handled locally; doesn't affect publisher
        }
      }
    );

    // Cleanup subscription on unmount
    return unsubscribe;
  }, [context.events]);
}

function CareCoordinationApp({ context }: { context: MfeContext }) {
  useClaimEvents(context);  // Subscribe to events

  return <div>...</div>;
}
```

**Event Naming Convention:**

```text
{domain}.{entity}.{action}

Examples:

- claim.submitted
- member.eligibility.changed
- provider.credentialed
- payment.processed
- careplan.updated
```

**When to Use:**
- ✅ Domain events that other modules react to asynchronously
- ✅ One-to-many communication (one publisher, multiple subscribers)
- ✅ Workflow coordination without tight coupling
- ✅ Audit logging (all events captured centrally)
- ❌ Request-response patterns → Use Backend API
- ❌ Synchronous workflows requiring immediate response → Use Shared Context or Backend API
- ❌ Large data payloads → Use Backend API with event carrying ID only

