[patterns/application/micro-frontend/PTN-APP-MFE-008-micro-frontend-integration-overview.md#pattern-3-shared-context-implementation]

#### Pattern 3: Shared Context Implementation

**Shell Context Provider:**

```typescript
// shell/src/contexts/NotificationContext.tsx
import { createContext, useContext, useState, ReactNode } from 'react';

interface Notification {
  id: string;
  type: 'success' | 'error' | 'warning' | 'info';
  message: string;
  timestamp: Date;
}

interface NotificationContextType {
  notifications: Notification[];
  addNotification: (notification: Omit<Notification, 'id' | 'timestamp'>) => void;
  removeNotification: (id: string) => void;
  clearAll: () => void;
}

const NotificationContext = createContext<NotificationContextType | null>(null);

export function NotificationProvider({ children }: { children: ReactNode }) {
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const addNotification = (notif: Omit<Notification, 'id' | 'timestamp'>) => {
    const notification: Notification = {
      ...notif,
      id: `notif-${Date.now()}-${Math.random()}`,
      timestamp: new Date(),
    };

    setNotifications(prev => [...prev, notification]);

    // Auto-remove after 5 seconds
    setTimeout(() => {
      removeNotification(notification.id);
    }, 5000);
  };

  const removeNotification = (id: string) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  const clearAll = () => {
    setNotifications([]);
  };

  return (
    <NotificationContext.Provider
      value={{ notifications, addNotification, removeNotification, clearAll }}
    >
      {children}
    </NotificationContext.Provider>
  );
}

export function useNotifications() {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotifications must be used within NotificationProvider');
  }
  return context;
}
```

**Shell Integration:**

```typescript
// shell/src/App.tsx
import { NotificationProvider, useNotifications } from './contexts/NotificationContext';

export function App() {
  return (
    <NotificationProvider>
      <AppContent />
    </NotificationProvider>
  );
}

function AppContent() {
  const { notifications } = useNotifications();

  return (
    <div>
      <Header />
      {/* Global notification panel */}
      <NotificationPanel notifications={notifications} />

      <Routes>
        <Route path="/claims/*" element={<ClaimsMFE />} />
        <Route path="/provider/*" element={<ProviderMFE />} />
      </Routes>
    </div>
  );
}
```

**Micro-Frontend Consumer:**

```typescript
// claims-mfe/src/components/ClaimSubmissionForm.tsx
// Context passed via module props
function ClaimSubmissionForm({ notificationContext }) {
  async function handleSubmit(claimData) {
    try {
      await claimsApi.submitClaim(claimData);

      // Add success notification via shared context
      notificationContext.addNotification({
        type: 'success',
        message: 'Claim submitted successfully',
      });
    } catch (error) {
      // Add error notification via shared context
      notificationContext.addNotification({
        type: 'error',
        message: `Failed to submit claim: ${error.message}`,
      });
    }
  }

  return <form onSubmit={handleSubmit}>...</form>;
}
```

**When to Use:**
- ✅ Notifications/alerts displayed across all modules
- ✅ Shopping cart or wizard state spanning modules
- ✅ UI state requiring immediate synchronization (modals, sidebars)
- ✅ Small, frequently changing shared state
- ❌ Large datasets → Use Backend API
- ❌ State that doesn't need real-time sync → Use Shell-Provided Props
- ❌ Complex workflows → Use Event Bus + Backend API

