[patterns/application/micro-frontend/PTN-APP-MFE-008-micro-frontend-integration-overview.md#security-implementation-for-cross-module-communication]

#### Security Implementation for Cross-Module Communication

**Security Risks by Integration Pattern:**

| Integration Pattern | Security Risks | Mitigation Requirements |
|---------------------|---------------|-------------------------|
| Shell-Provided Props | Low—read-only, controlled by shell | Input validation, XSS sanitization |
| Event Bus | **High**—untrusted modules can inject malicious events | Schema validation, payload sanitization, allowlist |
| Shared Context | **High**—mutable state can be corrupted | Type guards, validation hooks, immutable patterns |
| Backend API | Medium—depends on API security | CORS, authentication, rate limiting, input validation |

**1. Event Bus Security (XSS and Injection Prevention):**

```typescript
// shell-application/src/events/SecureEventBus.ts
import DOMPurify from 'dompurify';

interface EventSchema {
  type: 'object';
  properties: Record<string, { type: string; pattern?: string }>;
  required?: string[];
}

class SecureEventBus {
  private allowedEvents: Map<string, EventSchema> = new Map([
    ['member.selected', {
      type: 'object',
      properties: {
        memberId: { type: 'string', pattern: '^[0-9a-f-]+$' },
        timestamp: { type: 'string' }
      },
      required: ['memberId']
    }],
    ['claim.submitted', {
      type: 'object',
      properties: {
        claimId: { type: 'string', pattern: '^CLM-[0-9]+$' },
        amount: { type: 'number' }
      },
      required: ['claimId']
    }]
  ]);

  publish<T>(eventName: string, payload: T): void {
    // 1. Validate event is registered (prevent arbitrary events)
    const schema = this.allowedEvents.get(eventName);
    if (!schema) {
      throw new SecurityError(`Event '${eventName}' not in allowed events registry`);
    }

    // 2. Validate payload structure
    if (!this.validateSchema(payload, schema)) {
      throw new SecurityError(`Payload validation failed for '${eventName}'`);
    }

    // 3. Sanitize string values (prevent XSS)
    const sanitized = this.sanitizePayload(payload);

    // 4. Log for security audit
    this.auditLog('event.published', { eventName, sanitized });

    // 5. Publish sanitized event
    this.eventEmitter.emit(eventName, sanitized);
  }

  private sanitizePayload(payload: unknown): unknown {
    if (typeof payload === 'string') {
      // Remove script tags, javascript: URIs, data: URIs
      return DOMPurify.sanitize(payload, {
        ALLOWED_TAGS: [],           // No HTML tags
        ALLOWED_ATTR: [],           // No attributes
        KEEP_CONTENT: true          // Keep text content
      });
    }

    if (Array.isArray(payload)) {
      return payload.map(item => this.sanitizePayload(item));
    }

    if (typeof payload === 'object' && payload !== null) {
      const sanitized: Record<string, unknown> = {};
      for (const [key, value] of Object.entries(payload)) {
        sanitized[key] = this.sanitizePayload(value);
      }
      return sanitized;
    }

    return payload; // numbers, booleans, null pass through
  }

  private validateSchema(payload: unknown, schema: EventSchema): boolean {
    if (typeof payload !== 'object' || payload === null) {
      return false;
    }

    // Validate required fields
    for (const field of schema.required || []) {
      if (!(field in payload)) {
        return false;
      }
    }

    // Validate field types and patterns
    for (const [key, value] of Object.entries(payload as Record<string, unknown>)) {
      const fieldSchema = schema.properties[key];
      if (!fieldSchema) {
        return false; // Unknown field
      }

      // Type check
      if (typeof value !== fieldSchema.type) {
        return false;
      }

      // Pattern check (for strings)
      if (fieldSchema.pattern && typeof value === 'string') {
        const regex = new RegExp(fieldSchema.pattern);
        if (!regex.test(value)) {
          return false;
        }
      }
    }

    return true;
  }
}
```

**2. Shared Context Security (Mutation Protection):**

```typescript
// shell-application/src/context/SecureSharedContext.tsx
import { produce } from 'immer';

interface NotificationState {
  notifications: Notification[];
}

// Use Immer for immutable updates
const useSecureSharedState = () => {
  const [state, setState] = useState<NotificationState>({ notifications: [] });

  const addNotification = useCallback((notification: Notification) => {
    // Validate notification structure
    if (!isValidNotification(notification)) {
      throw new SecurityError('Invalid notification structure');
    }

    // Sanitize message content
    const sanitized = {
      ...notification,
      message: DOMPurify.sanitize(notification.message, { ALLOWED_TAGS: [] })
    };

    // Immutable update (prevents accidental mutations)
    setState(produce(draft => {
      draft.notifications.push(sanitized);

      // Limit notifications (prevent memory exhaustion)
      if (draft.notifications.length > 50) {
        draft.notifications.shift();
      }
    }));
  }, []);

  return { state, addNotification };
};

function isValidNotification(n: unknown): n is Notification {
  return (
    typeof n === 'object' &&
    n !== null &&
    'id' in n &&
    'type' in n &&
    'message' in n &&
    typeof (n as Notification).message === 'string' &&
    ['success', 'error', 'warning', 'info'].includes((n as Notification).type)
  );
}
```

**3. Backend API Security (CORS and Authentication):**

```typescript
// shell-application/src/api/SecureApiClient.ts
class SecureApiClient {
  private baseUrl: string;
  private authToken: string | null = null;

  async fetch(endpoint: string, options: RequestInit = {}) {
    // 1. Validate endpoint (prevent SSRF)
    if (!this.isAllowedEndpoint(endpoint)) {
      throw new SecurityError(`Endpoint not in allowlist: ${endpoint}`);
    }

    // 2. Add authentication
    const headers = new Headers(options.headers);
    if (this.authToken) {
      headers.set('Authorization', `Bearer ${this.authToken}`);
    }

    // 3. Set secure headers
    headers.set('Content-Type', 'application/json');
    headers.set('X-Requested-With', 'XMLHttpRequest'); // CSRF protection

    // 4. Make request with timeout
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 30000); // 30s timeout

    try {
      const response = await fetch(`${this.baseUrl}${endpoint}`, {
        ...options,
        headers,
        credentials: 'include', // Send cookies for CSRF token
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      // 5. Validate response
      if (!response.ok) {
        throw new ApiError(`API request failed: ${response.status}`);
      }

      return response.json();
    } catch (error) {
      clearTimeout(timeoutId);
      if (error.name === 'AbortError') {
        throw new ApiError('Request timeout');
      }
      throw error;
    }
  }

  private isAllowedEndpoint(endpoint: string): boolean {
    const allowedPrefixes = [
      '/api/claims/',
      '/api/members/',
      '/api/providers/',
      '/api/eligibility/'
    ];

    return allowedPrefixes.some(prefix => endpoint.startsWith(prefix));
  }
}
```

**4. Rate Limiting and Abuse Prevention:**

```typescript
// shell-application/src/security/RateLimiter.ts
class RateLimiter {
  private eventCounts: Map<string, number[]> = new Map();
  private readonly MAX_EVENTS_PER_MINUTE = 100;

  checkRateLimit(moduleId: string, eventName: string): boolean {
    const key = `${moduleId}:${eventName}`;
    const now = Date.now();
    const oneMinuteAgo = now - 60000;

    // Get recent events for this module/event combination
    let timestamps = this.eventCounts.get(key) || [];

    // Remove events older than 1 minute
    timestamps = timestamps.filter(ts => ts > oneMinuteAgo);

    // Check if limit exceeded
    if (timestamps.length >= this.MAX_EVENTS_PER_MINUTE) {
      console.error(
        `Rate limit exceeded for ${moduleId} publishing ${eventName}: ` +
        `${timestamps.length} events in last minute (max: ${this.MAX_EVENTS_PER_MINUTE})`
      );
      return false;
    }

    // Add current event
    timestamps.push(now);
    this.eventCounts.set(key, timestamps);

    return true;
  }
}
```

