### Example 1: Claims-to-Care Coordination Event Flow

**Scenario:** When claim is submitted, Care Coordination MFE triggers care gap analysis.

**Implementation:**

```typescript
// 1. Claims MFE publishes event
function ClaimSubmissionForm({ context }) {
  async function handleSubmit(claimData) {
    const claim = await claimsApi.submitClaim(claimData);

    context.events.publish(
      'claim.submitted',
      {
        claimId: claim.id,
        memberId: claim.memberId,
        providerId: claim.providerId,
        amount: claim.totalAmount,
        serviceDate: claim.serviceDate,
        submittedAt: new Date().toISOString(),
      },
      ClaimSubmittedEventSchema
    );
  }
}

// 2. Care Coordination MFE subscribes
function CareCoordinationApp({ context }) {
  useEffect(() => {
    const unsubscribe = context.events.subscribe('claim.submitted', async (event) => {
      // Trigger care gap analysis in background
      await careGapService.analyzeCaregaps(event.memberId);

      // Optionally add notification
      context.notifications.addNotification({
        type: 'info',
        message: `Care gap analysis initiated for member ${event.memberId}`,
      });
    });

    return unsubscribe;
  }, []);
}
```

